wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(52291121182111443)
,p_event_id=>wwv_flow_imp.id(52290979166111442)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'$s("P7_ELECTED_ROWS", ""); //seteo nada a selected rows',
'',
'// IG id estatico para el interactivegrid que se debe definir -> IG_REST',
'var gridView = apex.region("IG_REST").widget().interactiveGrid("getViews").grid; //por JSDoc me paro en el IG ',
'',
'var records = gridView.getSelectedRecords(); //guardo los seleccionados ',
'',
'var objType;',
'',
'// define un objeto del tipo JSON vacio para los registros seleccionados',
'',
'var selRecords = {',
' "rows": []',
'};',
'',
'var selRecordsJSON;',
'',
'',
'//si hay registros seleccionados',
'if (records.length > 0) {',
'    if (confirm("Quiere mover los registros seleccionados para armar el driver? Por favor, confirme.")) ',
'    {',
'        $.each(records, function(i, r) {',
'            // uso el id definido como PK para el IG',
'            objID = gridView.model.getRecordId(r);',
'',
unistr('            // Tambi\00E9n se puede obtener valores de otras columnas usando el siguiente c\00F3digo'),
'            // por ejemplo ENAME es nombre de la columna en un IG',
'            //empName = gridView.model.getValue(r, "ENAME");',
'            // meto los registros seleccionados en un array',
'            //alert ("objID "+objID);',
'            selRecords.rows.push({',
'                "objID": objID',
'                //,"objCode":objCode //no va mas, falla para casos que utilizan mas parametros',
'                });',
'        });',
'',
'',
'        // convert JSON en string',
'        selRecordsJSON = JSON.stringify(selRecords);',
'        console.log(selRecordsJSON);',
'        //submit de la pagina con el request del boton, uso el seteo de la propiedad con el json casteado',
'        apex.page.submit({',
'            request: "P7_BTN_ADD",',
'            set:    {',
'                    "P7_ELECTED_ROWS": selRecordsJSON',
'                    },',
'            showWait: true //espera',
'        });',
'',
'    }',
'    } else {',
'        alert ("Por favor seleccione al menos una linea.");',
'    }'))
);
