wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(50889953637714748)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'callRestfullObjetos'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_data          CLOB;',
'    l_object_desc   varchar2(200):= null;',
'    l_amb_url	    varchar2(1000) := null;',
'    l_bearer        VARCHAR2(1000);',
'    l_url           varchar2(2000) := null;    ',
'    l_modulo	    varchar2(500) :=  ''olt/rest/ebs/fnd/objects/?pTypeCode='';',
'    v_rows          NUMBER; --PLS_INTEGER;',
'    l_cant          number:= 0;',
'    l_session_id    NUMBER := APEX_CUSTOM_AUTH.GET_SESSION_ID;',
'    l_user_id       NUMBER := APEX_UTIL.GET_CURRENT_USER_ID;',
'',
'    l_errors        varchar2(32000):=null;',
'    l_sequence      varchar2(20) := ''callRestfullObjects'';',
'    l_step          number:=0;',
'',
'    -------------',
'    --p_ambiente  varchar2(20) := ''DESA'';',
'',
'    --User Exceptions',
'    INSERT_ERR          EXCEPTION;',
'    NO_AMBIENT          EXCEPTION;',
'    NO_MAKE_REST_REQ    EXCEPTION;',
'    NO_LINE_TYPE        EXCEPTION;',
'    NO_AMBIENT_SET      EXCEPTION;',
'BEGIN',
'  ',
'    XX_APX_APP_UTILS_PK.insert_debug(l_sequence,''Inicio'');',
'    XX_APX_APP_UTILS_PK.insert_debug(l_sequence,''LINE_TYPE_CODE: ''||:P7_OBJECT_TYPE_LV);',
'    :P7_LOG := '''';',
'    --obtengo descripcion del objeto ver de agregar un util apx con esto',
'    begin',
'        select  LINE_TYPE_DESC',
'        into    l_object_desc',
'        from    XX_APX_LINE_TYPES  ',
'        where   LINE_TYPE_CODE = :P7_OBJECT_TYPE_LV;',
'',
'        l_object_desc := replace(l_object_desc,'' '',''%20'');',
'',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            l_errors:=l_sequence||'' Error Buscando tipo de linea ''||NVL(:P7_OBJECT_TYPE_LV, ''NULL'')||'', ''||sqlerrm;',
'            raise NO_LINE_TYPE;',
'    END;',
'        ',
'    XX_APX_APP_UTILS_PK.insert_debug(l_sequence,''Buscando ambiente para ''||:P7_AMBIENT_LV);',
'',
'    BEGIN',
'        select  url_ambient, AUTH_AMBIENT',
'    	into    l_amb_url, l_bearer',
'    	from    xx_apx_ambients',
'    	where   cod_ambient = :P7_AMBIENT_LV; ',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            l_errors:=l_sequence||'' Error Buscando URL Ambiente para ''||nvl(:P7_AMBIENT_LV,''NULL'')||'', ''||sqlerrm;',
'            raise NO_AMBIENT;            ',
'    END;',
'    --:P7_LOG := :P7_LOG||'' - ''||:P7_AMBIENT_LV;',
'    ',
'    BEGIN',
'        xx_apx_app_utils_pk.app_sets_prc(p_ambiente => :P7_AMBIENT_LV );',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            l_errors:=l_sequence||''Error seteando Ambiente para ''||nvl(:P7_AMBIENT_LV,''NULL'')||'', ''||sqlerrm;',
'            raise NO_AMBIENT_SET;  ',
'    END;',
'',
'    --Armo URL Rest  ',
'    l_url := l_amb_url||l_modulo||:P7_OBJECT_TYPE_LV||''&pTypeDesc=''||l_object_desc||''&pAppShortName=''||:P7_APPLICATION_LV||''&pObjType=''||replace(:P7_OBJECT_NAME,'' '',''%20'') --UPPER(replace(:P7_OBJECT_NAME,'' '',''%20''))',
'    ||''&pAdditional1=''||:P7_ADDITIONAL_1||''&pAdditional2=''||replace(:P7_ADDITIONAL_2,'' '',''%20'')||''&pAdditional3=''||:P7_ADDITIONAL_3||''&pAdditional4=''||:P7_ADDITIONAL_4||'''';',
'    ',
'    XX_APX_APP_UTILS_PK.insert_debug(l_sequence,''Url: ''||l_url);',
'',
'    --borro ejecucion anterior',
'    BEGIN',
'        DELETE FROM XX_APX_SRCH_OBJ_GTT',
'        where session_id = l_session_id',
'        and  user_id = l_user_id;',
'',
'        COMMIT;',
'    EXCEPTION',
'        WHEN OTHERS THEN ',
'            l_errors:=l_sequence||'' ''||l_errors||'' Error Borrando GTT: ''||sqlerrm;',
'    END;',
'    --llamo al api',
'',
'    --:P7_LOG := :P7_LOG||'' - ''||l_url;',
'    BEGIN',
'        l_data := APEX_WEB_SERVICE.make_rest_request(',
'    													p_url => l_url,',
'    													p_http_method => ''GET''',
'    												);',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            --:P7_LOG := :P7_LOG||'' - EXCEpTION pre l_data  ''||SQLERRM;',
'            l_errors := ''Error en llamado a RestFull Service, ''||SQLERRM;',
'            raise NO_MAKE_REST_REQ;',
'    END;',
'	:P7_RESULT := 	l_data;',
'	-- Procesar el JSON devuelto',
'    APEX_JSON.PARSE(l_data);',
'    v_rows := APEX_JSON.GET_COUNT(''items'');',
'    ',
'',
'    -- Insertar cada fila del JSON en la tabla TMP_REST_DATA',
'    BEGIN',
'        FOR i IN 1..v_rows LOOP',
'',
'            INSERT INTO XX_APX_SRCH_OBJ_GTT (OBJ_CODE,',
'        									OBJ_DESCRIPTION,',
'        									APP_ID,',
'        									APP_NAME,',
'        									APP_SHORT_NAME,',
'        									OBJ_TYPE,',
'        									OBJ_NAME,',
'        									OBJ_DESC,',
'                                            session_id,',
'                                            user_id,',
'                                            ADDITIONAL_1,',
'                                            ADDITIONAL_2,',
'                                            ADDITIONAL_3,',
'                                            ADDITIONAL_4)',
'            VALUES (',
'                APEX_JSON.GET_VARCHAR2(''items[%d].OBJ_CODE'', i),',
'                APEX_JSON.GET_VARCHAR2(''items[%d].OBJ_DESCRIPTION'', i),',
'    			APEX_JSON.GET_VARCHAR2(''items[%d].APP_ID'', i),',
'                APEX_JSON.GET_VARCHAR2(''items[%d].APP_NAME'', i),',
'    			APEX_JSON.GET_VARCHAR2(''items[%d].APP_SHORT_NAME'', i),',
'                APEX_JSON.GET_VARCHAR2(''items[%d].OBJ_TYPE'', i),',
'    			APEX_JSON.GET_VARCHAR2(''items[%d].OBJ_NAME'', i),',
'                APEX_JSON.GET_VARCHAR2(''items[%d].OBJ_DESC'', i),',
'                l_session_id,',
'                l_user_id,',
'                APEX_JSON.GET_VARCHAR2(''items[%d].ADDITIONAL_1'', i),',
'                APEX_JSON.GET_VARCHAR2(''items[%d].ADDITIONAL_2'', i),',
'                APEX_JSON.GET_VARCHAR2(''items[%d].ADDITIONAL_3'', i),',
'                APEX_JSON.GET_VARCHAR2(''items[%d].ADDITIONAL_4'', i)',
'            );',
'            l_cant := l_cant + sql%rowcount;',
'        END LOOP;',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            l_errors:= ''Error insertando en tabla temp de objetos: ''||sqlerrm;',
'            RAISE INSERT_ERR;',
'    END;',
'',
'    --:P10_ejecucion := l_cant;',
'    --:P4_URL := l_cant;',
'',
'    COMMIT;',
'',
'    --:P7_LOG :=	:P7_LOG||'' v_rows ''||v_rows||'' l_errors ''|| l_errors;',
'EXCEPTION',
'    WHEN NO_AMBIENT THEN',
'        :P7_LOG := l_errors;',
'        XX_APX_APP_UTILS_PK.insert_debug(l_sequence,''Error NO_AMBIENT: ''||l_errors);',
'        apex_error.add_error(',
'                            p_message           => l_errors,',
'                            p_display_location  => apex_error.c_inline_in_notification',
'                            );',
'    WHEN INSERT_ERR THEN',
'        :P7_LOG := ''Error INSERT_ERR: ''||:P7_LOG||''l_object_desc ''||l_object_desc||'' v_rows ''||v_rows||'' l_bearer ''||l_bearer||'' l_url: ''||l_url||'' Error general: ''||sqlerrm;',
'        XX_APX_APP_UTILS_PK.insert_debug(l_sequence,''Error INSERT_ERR: ''||:P7_LOG||''l_object_desc ''||l_object_desc||'' v_rows ''||v_rows||'' l_bearer ''||l_bearer||'' l_url: ''||l_url||'' Error general: ''||sqlerrm);',
'        apex_error.add_error(',
'                            p_message           => l_errors,',
'                            p_display_location  => apex_error.c_inline_in_notification',
'                            );',
'    WHEN NO_MAKE_REST_REQ THEN',
'        :P7_LOG := ''Error NO_MAKE_REST_REQ: ''||:P7_LOG||''l_object_desc ''||l_object_desc||'' v_rows ''||v_rows --||'' l_bearer ''||l_bearer',
'                                                ||'' l_url: ''||l_url;',
'        XX_APX_APP_UTILS_PK.insert_debug(l_sequence,''Error NO_MAKE_REST_REQ: ''||:P7_LOG||''l_object_desc ''||l_object_desc||'' v_rows ''||v_rows --||'' l_bearer ''||l_bearer',
'                                                ||'' l_url: ''||l_url);                                        ',
'        apex_error.add_error(',
'                            p_message           => l_errors,',
'                            p_display_location  => apex_error.c_inline_in_notification',
'                            );',
'    WHEN NO_LINE_TYPE THEN ',
'        XX_APX_APP_UTILS_PK.insert_debug(l_sequence,''Error NO_LINE_TYPE: ''||l_errors);',
'        apex_error.add_error(',
'                            p_message           => l_errors,',
'                            p_display_location  => apex_error.c_inline_in_notification',
'                            );   ',
'    WHEN NO_AMBIENT_SET THEN ',
'        XX_APX_APP_UTILS_PK.insert_debug(l_sequence,''Error NO_LINE_TYPE: ''||l_errors);',
'        apex_error.add_error(',
'                            p_message           => l_errors,',
'                            p_display_location  => apex_error.c_inline_in_notification',
'                            );                                            ',
'    WHEN OTHERS THEN    ',
'        l_errors:= ''Error general, Ambiente: ''||:P7_AMBIENT_LV||'' Objeto: ''||l_object_desc||'' Desc del error: ''||sqlerrm;',
'        --:P7_LOG := ''Otros Errores: ''||:P7_LOG||''l_object_desc ''||l_object_desc||'' v_rows ''||v_rows||'' l_bearer ''||l_bearer||'' l_url: ''||l_url||'' Error general: ''||sqlerrm;',
'        XX_APX_APP_UTILS_PK.insert_debug(l_sequence,''Error OTHERS: ''||l_errors);',
'        apex_error.add_error(',
'                            p_message           => l_errors,',
'                            p_display_location  => apex_error.c_inline_in_notification',
'                            );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Error en llamado a RestFull Service Objetos'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(46477608483898256)
,p_internal_uid=>19256480906417212
);
