wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(52291191851111444)
,p_process_sequence=>50
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'cargaSelectedTable'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'',
'	l_row_count      	pls_integer;',
'	l_user_id			NUMBER := APEX_UTIL.GET_CURRENT_USER_ID;',
'	l_session_id 		NUMBER := APEX_CUSTOM_AUTH.GET_SESSION_ID;',
'	l_obj_type			VARCHAR2(2000);	',
'    l_obj_code      	VARCHAR2(2000);',
'	l_description   	VARCHAR2(4000);',
'	l_app_id        	NUMBER;',
'	l_app_name      	VARCHAR2(240);',
'	l_app_short_name    VARCHAR2(50);',
'	l_obj_nombre    	VARCHAR2(2400);',
'	l_obj_desc      	VARCHAR2(2400);',
'    l_additional_1      VARCHAR2(4000);',
'    l_additional_2      VARCHAR2(4000);',
'    l_additional_3      VARCHAR2(4000);',
'    l_additional_4      VARCHAR2(4000);',
'    l_obj_code2      	VARCHAR2(2000);',
'    --',
'    l_obj_id            VARCHAR2(50);',
'    l_srch_id           NUMBER;',
'    --',
'    l_errors            VARCHAR2(32000);',
'',
'BEGIN',
'  ',
'	apex_json.parse(:P7_ELECTED_ROWS);  ',
'	l_row_count := apex_json.get_count(''rows'');',
'',
'    --:p7_log := :p7_log||'' -l_row_count ''||l_row_count;',
'	',
'   /* DELETE FROM TMP_DEST_LKP_DATA',
'    where session_id = l_session_id;',
'    COMMIT;	*/						 ',
'  -- loop through the selected rows',
'	FOR i IN 1..l_row_count',
'	LOOP',
'        l_obj_id :=  null;',
'',
'        l_obj_id:= 	APEX_JSON.GET_VARCHAR2(''rows[%d].objID'', i);	',
'',
'        --:p7_log := :p7_log||'' -l_obj_code2 ''||l_obj_code2||'' -l_obj_type ''||l_obj_type;',
'        ',
'		SELECT 	xasog.obj_code,',
'				xasog.obj_description, ',
'				xasog.app_id, ',
'				xasog.app_name,',
'				xasog.app_short_name, ',
'				xasog.obj_type,',
'				xasog.obj_name,',
'				xasog.obj_desc,',
'                xasog.additional_1,',
'                xasog.additional_2,',
'                xasog.additional_3,',
'                xasog.additional_4,',
'                ID_SRCH',
'		INTO 	l_obj_code,',
'				l_description,',
'				l_app_id,',
'				l_app_name,',
'				l_app_short_name,',
'				l_obj_type,',
'				l_obj_nombre,',
'				l_obj_desc,',
'                l_additional_1,',
'                l_additional_2,',
'                l_additional_3,',
'                l_additional_4, ',
'                l_srch_id',
'		FROM 	xx_apx_srch_obj_gtt xasog',
'		WHERE 	1=1 --xasog.obj_type = l_obj_type',
'		AND 	xasog.session_id = l_session_id',
'		AND 	xasog.user_id = l_user_id',
'        and     xasog.ID_SRCH = to_number(l_obj_id);',
'	',
'	',
'							   ',
'		INSERT INTO XX_APX_SEL_OBJ_GTT (	',
'										obj_code',
'										,obj_description ',
'										,app_id ',
'										,app_name',
'										,app_short_name ',
'										,obj_type',
'										,obj_name',
'										,obj_desc',
'										,session_id ',
'										,user_id',
'                                        ,additional_1',
'                                        ,additional_2',
'                                        ,additional_3',
'                                        ,additional_4',
'										)',
'					VALUES 			( 	',
'										l_obj_code,',
'										l_description,',
'										l_app_id,',
'										l_app_name,',
'										l_app_short_name,',
'										l_obj_type,',
'										l_obj_nombre,',
'										l_obj_desc,',
'										l_session_id,',
'										l_user_id,',
'                                        l_additional_1,',
'                                        l_additional_2,',
'                                        l_additional_3,',
'                                        l_additional_4',
'									);	',
'',
'                                    COMMIT;		',
'                                    ',
'        --elimina de la temp para que no se pueda volver a agregar',
'        delete from   xx_apx_srch_obj_gtt xasog2',
'        where   1=1 ',
'        --AND     xasog2.obj_type = l_obj_type',
'        --AND     xasog2.obj_name = l_obj_nombre',
'        --AND     xasog2.obj_desc = l_obj_desc',
'        --AND     xasog2.additional_1 = l_additional_1',
'        --AND     xasog2.additional_2 = l_additional_2',
'        --AND     xasog2.additional_3 = l_additional_3',
'        --AND     xasog2.additional_4 = l_additional_4',
'		--AND 	xasog2.session_id = l_session_id',
'		--AND 	xasog2.user_id = l_user_id  ',
'        and     xasog2.ID_SRCH = l_srch_id --to_number(l_obj_id)',
'        ;                   ',
'        COMMIT;			   ',
'	END LOOP;',
'',
'exception',
'    when others then',
'          --:p7_log := :p7_log||'' - ''||l_obj_code2||'' error ''||sqlerrm; ',
'          l_errors := ''Error al cargar seleccion, '' ||l_errors ||''tipo objeto: ''||l_obj_type||''codigo objeto: ''||l_obj_code||'', ''||sqlerrm;',
'          :p7_log := l_errors;',
'          apex_error.add_error  (',
'                                    p_message          => l_errors,',
'                                    p_display_location => apex_error.c_inline_in_notification',
'                                );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(50890642487714755)
,p_internal_uid=>20657719119813908
);
