,p_plug_name=>'DownloadRegion'
,p_title=>'Lineas Generadas por Paquete'
,p_region_name=>'DownloadRegion'
,p_region_template_options=>'#DEFAULT#:t-Form--slimPadding'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(43175229741886426)
,p_plug_display_sequence=>40
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    ID_SENTENCE,',
'    ID_PACKAGE,',
'    USER_ID,',
'    USER_NAME,',
'    OBJ_CODE,',
'    (select line_type_desc',
'    from XX_APX_LINE_TYPES',
'    where line_type_code = OBJ_CODE) OBJECT_TYPE,',
'    ID_SEL,',
'    FND_SENTENCE,',
'    SEQUENCE,',
'    (select desc_ambient',
'from xx_apx_ambients',
'where cod_ambient = REQ_AMBIENT) REQ_AMBIENT,',
'    EXECUTABLE,',
'    REQUEST_ID,',
'    STATUS,',
'    CASE ',
'        WHEN status = ''COMPLETE'' THEN ''#28a745''',
'        WHEN status IN (''ERROR'', ''FAILED'') THEN ''#dc3545''',
'        WHEN status IN (''PROCESSING'', ''PENDING'') THEN ''#856404''',
'        ELSE ''#6c757d''',
'    END as case_when_status,',
'    CASE ',
'        WHEN status = ''COMPLETE'' THEN ''#d4edda''',
'        WHEN status IN (''ERROR'', ''FAILED'') THEN ''#f8d7da''',
'        WHEN status IN (''PROCESSING'', ''PENDING'') THEN ''#fff3cd''',
'        ELSE ''#f8f9fa''',
'    END as bg_color,',
'    DESC_STATUS,',
'    CASE ',
'        WHEN DESC_STATUS = ''NORMAL'' THEN ''#28a745''',
'        WHEN DESC_STATUS IN (''ERROR'', ''FAILED'') THEN ''#dc3545''',
'        WHEN DESC_STATUS IN (''PROCESSING'', ''PENDING'') THEN ''#856404''',
'        ELSE ''#6c757d''',
'    END as case_when_status_desc,',
'    CASE ',
'        WHEN DESC_STATUS = ''NORMAL'' THEN ''#d4edda''',
'        WHEN DESC_STATUS IN (''ERROR'', ''FAILED'') THEN ''#f8d7da''',
'        WHEN DESC_STATUS IN (''PROCESSING'', ''PENDING'') THEN ''#fff3cd''',
'        ELSE ''#f8f9fa''',
'    END as bg_color_desc,',
'    FILE_NAME,',
'    clob_file,',
'     BLOB_FILE,',
unistr('   ''application/octet-stream'' AS MIME_TYPE,  -- O el MIME type espec\00EDfico si lo tienes text/plain'),
'   FILE_NAME AS DOWNLOAD_FILENAME,',
'   dbms_lob.getlength(BLOB_FILE) long_blob,',
'   pkg_description description',
'FROM XX_APX_SENTENCES_BY_REQUEST',
'WHERE ID_PACKAGE = :P14_ID_PACKAGE',
'AND USER_ID = :P14_USER_ID',
'ORDER BY ID_SENTENCE DESC'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
