wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(3467310550382710)
,p_event_id=>wwv_flow_imp.id(3467209548382709)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var allComplete = true;',
'var hasData = false;',
'var completeCount = 0;',
'var totalCount = 0;',
'',
'$(''#DownloadRegion .t-Report-report tbody tr'').each(function() {',
'    hasData = true;',
'    totalCount++;',
'    var statusCell = $(this).find(''td[headers="STATUS"]'').text().trim();',
'    if (statusCell === ''COMPLETE'') {',
'        completeCount++;',
'    } else {',
'        allComplete = false;',
'    }',
'});',
'',
'if (hasData) {',
'    if (allComplete) {',
unistr('        // Todos completos - mostrar \00E9xito'),
'        apex.message.clearMessages();',
unistr('        apex.message.showPageSuccess(''\00BF Informaci\00F3n generada correctamente ('' + totalCount + '' registros)'');'),
'        ',
'        setTimeout(function() {',
'            apex.message.clearMessages();',
'        }, 4000);',
'    } else {',
'        // Parcialmente completo - actualizar mensaje',
'        apex.message.clearMessages();',
unistr('        apex.message.showPageSuccess(''\00BF Procesando... ('' + completeCount + ''/'' + totalCount + '' completados)'');'),
'    }',
'}',
''))
);
