,p_plug_query_exp_enclosed_by=>'"'
,p_plug_query_strip_html=>'N'
);
wwv_flow_imp_page.create_report_columns(
 p_id=>wwv_flow_imp.id(3470489039382741)
,p_query_column_id=>1
