wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(3104336375858081)
,p_process_sequence=>10
,p_process_point=>'BEFORE_BOX_BODY'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'RefreshByRest'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_count         NUMBER := 0;',
'    l_url           VARCHAR2(4000) := null; --''https://tu-servidor/rest/endpoint''; -- Cambia por tu URL',
'	l_modulo	    varchar2(500) :=  ''olt/rest/ebs/fnd/getClob/?pPkgId='';',
'    l_amb_url	    varchar2(1000) := null;',
'    l_bearer        VARCHAR2(1000);',
'    l_data          CLOB;',
'    v_rows          NUMBER;',
'',
'    l_errors        varchar2(32000):=null;',
'    l_sequence      varchar2(40) := ''refreshByPackage - '';',
'    l_step          number:=0;',
'    ',
'    --''https://ebs-fsservices-dev.despegar.com/ordsd/xx_apex/olt/rest/ebs/fnd/getClob/?pPkgId=65&pApxUsrId=11040689572813335',
'    --&pApxIdSent=&pApxIdSel=&pApxSeq=''',
'    ',
'    l_request_body  CLOB;',
'    l_response      CLOB;',
'    l_upd           NUMBER:=0;',
'    l_tot_upd       NUMBER:=0;',
'    ',
'    NO_AMBIENT          EXCEPTION;',
'    NO_MAKE_REST_REQ    EXCEPTION;',
'    NO_AMBIENT_SET      EXCEPTION;',
'    ',
'    -- Cursor para obtener registros a actualizar',
'    CURSOR c_records IS',
'        SELECT ID_SENTENCE, ID_PACKAGE, USER_ID, ID_SEL, SEQUENCE, REQ_AMBIENT,',
'               REQUEST_ID, STATUS, DESC_STATUS, FILE_NAME, BLOB_FILE',
'        FROM XX_APX_SENTENCES_BY_REQUEST',
'        WHERE ID_PACKAGE = :P23_ID_PACKAGE;',
'          --AND USER_ID = :P23_USER_ID;',
'          --AND (STATUS != ''COMPLETE'' OR DESC_STATUS != ''NORMAL'');',
'          ',
'BEGIN',
'    -- Solo proceder si hay registros que actualizar',
'    SELECT COUNT(*)',
'    INTO l_count',
'    FROM XX_APX_SENTENCES_BY_REQUEST',
'    WHERE ID_PACKAGE = :P23_ID_PACKAGE',
'      --AND USER_ID = :P23_USER_ID',
'      AND ((STATUS != ''COMPLETE'' OR STATUS IS NULL) ',
'        OR (DESC_STATUS != ''NORMAL'' OR DESC_STATUS IS NULL));',
'',
'    --llamo al rest y actualizo la tabla con la respuesta del rest',
'',
'    xx_apx_app_utils_pk.insert_debug(l_sequence,''INICIO'');',
'    if l_count > 0 then',
'    apex_application.g_notification := ''Por favor, aguarde a que termine de cargar los archivos para dejarlos disponibles para descarga'';',
'    end if;',
'    ',
'',
'    For rec IN c_records LOOP',
unistr('        -- Aqu\00ED puedes construir el cuerpo de la solicitud para cada registro'),
unistr('        -- Por ejemplo, podr\00EDas construir un JSON espec\00EDfico para cada registro'),
'        -- o acumularlos en un solo JSON si tu REST API lo permite. ',
'        IF (rec.STATUS != ''COMPLETE'') or (rec.STATUS IS NULL )then        ',
'            xx_apx_app_utils_pk.insert_debug(l_sequence,''ID_SENTENCE ''||rec.ID_SENTENCE);',
'            BEGIN',
'                select  url_ambient, AUTH_AMBIENT',
'                into    l_amb_url, l_bearer',
'                from    xx_apx_ambients',
'                where   cod_ambient = rec.REQ_AMBIENT; ',
'            EXCEPTION',
'                WHEN OTHERS THEN',
'                    l_errors:=l_sequence||'' Error Buscando URL Ambiente para ''||nvl(rec.REQ_AMBIENT,''NULL'')||'', ''||sqlerrm;',
'                    raise NO_AMBIENT;            ',
'            END;',
'            --:P7_LOG := :P7_LOG||'' - ''||:P7_AMBIENT_LV;',
'            ',
'            BEGIN',
'                xx_apx_app_utils_pk.app_sets_prc(p_ambiente => rec.REQ_AMBIENT );',
'            EXCEPTION',
'                WHEN OTHERS THEN',
'                    l_errors:=l_sequence||''Error seteando Ambiente para ''||nvl(rec.REQ_AMBIENT,''NULL'')||'', ''||sqlerrm;',
'                    raise NO_AMBIENT_SET;  ',
'            END;',
'',
'            --Armo URL Rest  ',
'            l_url := l_amb_url||l_modulo||rec.ID_PACKAGE||''&pApxUsrId=''||rec.USER_ID||''&pApxIdSent=''||rec.ID_SENTENCE||''&pApxIdSel=''||rec.ID_SEL||''&pApxSeq=''||rec.SEQUENCE||'''';',
'            xx_apx_app_utils_pk.insert_debug(l_sequence,''l_url ''||l_url);',
'            BEGIN',
'                l_data := APEX_WEB_SERVICE.make_rest_request(',
'                                                                p_url => l_url,',
'                                                                p_http_method => ''GET''',
'                                                            );',
'            EXCEPTION',
'                WHEN OTHERS THEN',
'                    ',
'                    l_errors := ''Error en llamado a RestFull Service, ''||SQLERRM;',
'                    xx_apx_app_utils_pk.insert_debug(l_sequence,''l_errors 1 ''||l_errors);',
'                    raise NO_MAKE_REST_REQ;',
'            END;',
'',
'            xx_apx_app_utils_pk.insert_debug(l_sequence,''Procesa ldata ''||l_errors);',
'            -- Procesar el JSON devuelto',
'            APEX_JSON.PARSE(l_data);',
'            v_rows := APEX_JSON.GET_COUNT(''files'');',
'            xx_apx_app_utils_pk.insert_debug(l_sequence,''v_rows ''||v_rows);',
'',
'    -------------------------------------------------------------------------------------',
'            --update de cada registro con la respuesta del rest',
'            FOR i IN 1..v_rows LOOP',
unistr('                -- Ejemplo de c\00F3mo obtener datos del JSON y hacer un UPDATE'),
'                --campos a updatear , BLOB_FILE',
'                DECLARE',
'                    l_file_name        VARCHAR2(255);',
'                    l_status           VARCHAR2(50);',
'                    l_desc_status      VARCHAR2(255);',
'                    l_request_id       NUMBER;',
'                    l_clob_file        CLOB;',
'                    l_blob_file        BLOB;',
'                    l_blob_target      BLOB;',
'                    l_package_id       NUMBER;',
'                    l_id_apx_sentence  NUMBER;',
'                    l_apx_sequence     NUMBER;',
'                    l_apx_user_id      NUMBER;',
'                BEGIN',
'                    l_file_name       := APEX_JSON.GET_VARCHAR2(''files[%d].file_name'', i);',
'                    l_status          := APEX_JSON.GET_VARCHAR2(''files[%d].status'', i);',
'                    l_desc_status     := APEX_JSON.GET_VARCHAR2(''files[%d].desc_status'', i);    ',
'                    l_request_id      := APEX_JSON.GET_NUMBER(''files[%d].request_id'', i);',
'                    l_package_id      := APEX_JSON.GET_NUMBER(''files[%d].package_id'', i);',
'                    l_id_apx_sentence := APEX_JSON.GET_NUMBER(''files[%d].id_apx_sentence'', i);',
'                    l_apx_sequence    := APEX_JSON.GET_NUMBER(''files[%d].apx_sequence'', i);',
'                    l_apx_user_id     := APEX_JSON.GET_NUMBER(''files[%d].apx_user_id'', i);',
'',
'                    -- blob_file viene como CLOB en Base64 dentro del JSON.',
'                    -- En APEX 24.1 usamos APEX_WEB_SERVICE.CLOBBASE642BLOB para decodificarlo a BLOB.',
'                    l_clob_file := APEX_JSON.GET_CLOB(''files[%d].clob_file'', i);',
'                    xx_apx_app_utils_pk.insert_debug(l_sequence,''l_clob_file tamanio ''||DBMS_LOB.GETLENGTH(l_clob_file)); ',
'',
'                    IF l_clob_file IS NOT NULL AND DBMS_LOB.GETLENGTH(l_clob_file) > 0 THEN',
'                        xx_apx_app_utils_pk.insert_debug(l_sequence,''convierte a blob'');',
'                        l_blob_file := APEX_WEB_SERVICE.CLOBBASE642BLOB(l_clob_file);',
'                    END IF;',
'',
'                    xx_apx_app_utils_pk.insert_debug(l_sequence,''l_BLOB_file tamanio ''||DBMS_LOB.GETLENGTH(l_blob_file));',
'',
'                    -- Actualizo el registro correspondiente con los datos devueltos por el REST',
'                    BEGIN',
'                        -- Para BLOBs grandes no conviene asignar directo en el UPDATE.',
'                        -- Usamos EMPTY_BLOB() + RETURNING para obtener el LOB locator persistente',
'                        -- y luego copiamos el contenido del BLOB temporal con DBMS_LOB.COPY.',
'                        UPDATE XX_APX_SENTENCES_BY_REQUEST',
'                           SET FILE_NAME   = l_file_name,',
'                               STATUS      = l_status,',
'                               DESC_STATUS = l_desc_status,',
'                               REQUEST_ID  = l_request_id,',
'                               CLOB_FILE   = l_clob_file,',
'                               MIMETYPE    = ''text/plain'',',
'                               LASTUPD     = SYSDATE,',
'                               BLOB_FILE   = EMPTY_BLOB()',
'                         WHERE ID_PACKAGE  = l_package_id',
'                           AND ID_SENTENCE = l_id_apx_sentence',
'                           AND SEQUENCE    = l_apx_sequence',
'                           AND USER_ID     = l_apx_user_id',
'                         RETURNING BLOB_FILE INTO l_blob_target;',
'',
'                        l_upd := SQL%ROWCOUNT;',
'',
'                        IF l_upd = 0 THEN',
unistr('                            l_errors := ''No se encontr\00F3 registro para actualizar con ID_SENTENCE '' || l_id_apx_sentence;'),
unistr('                            -- Opcional: podr\00EDas decidir insertar un nuevo registro si no existe'),
'                        ELSIF l_blob_file IS NOT NULL AND DBMS_LOB.GETLENGTH(l_blob_file) > 0  THEN',
'                        xx_apx_app_utils_pk.insert_debug(l_sequence,''llamando a copy'');',
'                            -- Copiamos el contenido del BLOB temporal al LOB persistente devuelto',
'                            DBMS_LOB.COPY(',
'                                dest_lob    => l_blob_target,',
'                                src_lob     => l_blob_file,',
'                                amount      => DBMS_LOB.GETLENGTH(l_blob_file),',
'                                dest_offset => 1,',
'                                src_offset  => 1',
'                            );',
'',
'                            xx_apx_app_utils_pk.insert_debug(''l_sequence'',''post copy ''||DBMS_LOB.GETLENGTH(l_blob_file));',
'                        END IF;',
'',
'                        -- Liberamos el LOB temporal si fue creado',
'                        IF l_blob_file IS NOT NULL',
'                           AND DBMS_LOB.ISTEMPORARY(l_blob_file) = 1',
'                        THEN',
'                            DBMS_LOB.FREETEMPORARY(l_blob_file);',
'                        END IF;',
'                    EXCEPTION',
'                        WHEN OTHERS THEN',
'                            l_errors := ''Error actualizando registro con ID_SENTENCE '' || l_id_apx_sentence || '': '' || SQLERRM;',
'                            xx_apx_app_utils_pk.insert_debug(l_sequence,''l_errors 2 ''||l_errors);',
'                            --raise UPDATE_ERROR;',
'                    END;   ',
'',
'                    l_tot_upd := l_tot_upd + l_upd; ',
'',
'                END;',
'                --xx_apx_app_utils_pk.insert_debug(''clob BLOB ERROR '',l_errors);',
'            END LOOP;',
'        end if; --status != complete',
'-------------------------------------------------------------------------------------------',
'    END LOOP; --for rec IN c_records',
'    ',
'',
'',
'   ',
'    COMMIT;',
'    if l_count > 0 then',
'        apex_application.g_print_success_message := ''cantidad : '' || l_count || '', actualizados: '' || l_tot_upd || '', errores: '' || nvl(l_errors,''0'');',
'    end if;',
'exception    ',
'    WHEN NO_AMBIENT THEN',
'        ',
'        apex_error.add_error(',
'                            p_message           => l_errors,',
'                            p_display_location  => apex_error.c_inline_in_notification',
'                            );',
'   ',
'    WHEN NO_MAKE_REST_REQ THEN',
'        ',
'        apex_error.add_error(',
'                            p_message           => l_errors,',
'                            p_display_location  => apex_error.c_inline_in_notification',
'                            );',
'  ',
'    WHEN NO_AMBIENT_SET THEN ',
'        apex_error.add_error(',
'                            p_message           => l_errors,',
'                            p_display_location  => apex_error.c_inline_in_notification',
'                            );                                            ',
'    WHEN OTHERS THEN    ',
'        l_errors:= ''Error general, Desc del error: ''||sqlerrm;',
'        --:P7_LOG := ''Otros Errores: ''||:P7_LOG||''l_object_desc ''||l_object_desc||'' v_rows ''||v_rows||'' l_bearer ''||l_bearer||'' l_url: ''||l_url||'' Error general: ''||sqlerrm;',
'        apex_error.add_error(',
'                            p_message           => l_errors,',
'                            p_display_location  => apex_error.c_inline_in_notification',
'                            );    ',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'error llamando RefreshByRest'
,p_process_when_button_id=>wwv_flow_imp.id(3094729149858164)
,p_internal_uid=>3104336375858081
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(3104795567858078)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'DOWNLOAD_ZIP'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_zip_blob BLOB;',
'    l_count    PLS_INTEGER := 0;',
'BEGIN',
'    -- Proceso de tipo "Ajax Callback" llamado DOWNLOAD_ZIP.',
'    -- Se invoca desde JS apuntando directo a su URL, evitando branches',
'    -- y redirects que rompen wpg_docload.',
'',
'    DBMS_LOB.CREATETEMPORARY(l_zip_blob, TRUE, DBMS_LOB.SESSION);',
'',
'    FOR r IN (',
'        SELECT file_name, blob_file',
'          FROM XX_APX_SENTENCES_BY_REQUEST',
'         WHERE id_package = APEX_APPLICATION.G_X01     -- viene desde JS',
'           AND user_id    = APEX_APPLICATION.G_X02     -- viene desde JS',
'           AND blob_file IS NOT NULL',
'           AND file_name IS NOT NULL',
'    ) LOOP',
'        APEX_ZIP.ADD_FILE(',
'            p_zipped_blob => l_zip_blob,',
'            p_file_name   => r.file_name,',
'            p_content     => r.blob_file',
'        );',
'        l_count := l_count + 1;',
'    END LOOP;',
'',
'    IF l_count = 0 THEN',
'        DBMS_LOB.FREETEMPORARY(l_zip_blob);',
'        sys.htp.init;',
'        sys.owa_util.mime_header(''text/plain'', FALSE);',
'        sys.owa_util.http_header_close;',
'        sys.htp.p(''NO_FILES'');',
'        APEX_APPLICATION.STOP_APEX_ENGINE;',
'        RETURN;',
'    END IF;',
'',
'    APEX_ZIP.FINISH(p_zipped_blob => l_zip_blob);',
'',
'    sys.htp.init;',
'    sys.owa_util.mime_header(''application/zip'', FALSE);',
'    sys.htp.p(''Content-Length: '' || DBMS_LOB.GETLENGTH(l_zip_blob));',
'    sys.htp.p(''Content-Disposition: attachment; filename="archivos_pkg_''||:P23_ID_PACKAGE||''.zip"'');',
'    sys.htp.p(''Cache-Control: no-cache, no-store, must-revalidate'');',
'    sys.htp.p(''Pragma: no-cache'');',
'    sys.owa_util.http_header_close;',
'',
'    sys.wpg_docload.download_file(l_zip_blob);',
'',
'    APEX_APPLICATION.STOP_APEX_ENGINE;',
'EXCEPTION',
'    WHEN apex_application.e_stop_apex_engine THEN',
'        RAISE;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>3104795567858078
);
end;
